import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ConfirmDialogService } from '../../services/confirm-dialog.service';

@Component({
  selector: 'vx-confirm-dialog',
  standalone: true,
  imports: [CommonModule],
  template: `
    @if (svc.state().open) {
      <div class="d-flex align-items-center justify-content-center"
           style="position:fixed;inset:0;background:rgba(15,23,42,.45);z-index:2000;padding:1rem;"
           role="dialog" aria-modal="true" [attr.aria-label]="svc.state().title" (click)="svc.close(false)">
        <div class="vx-card p-4" style="width:100%;max-width:420px;" (click)="$event.stopPropagation()">
          <div class="d-flex align-items-start gap-3 mb-3">
            <span class="d-inline-flex align-items-center justify-content-center flex-shrink-0"
                  style="width:40px;height:40px;border-radius:12px;background:rgba(220,38,38,.1);color:#dc2626;">
              <i class="bi bi-exclamation-triangle-fill"></i>
            </span>
            <div class="flex-grow-1">
              <h6 class="fw-bold mb-1" style="color:#0f172a;">{{ svc.state().title }}</h6>
              <p class="mb-0 small" style="color:#64748b;">{{ svc.state().message }}</p>
            </div>
          </div>
          <div class="d-flex justify-content-end gap-2">
            <button class="btn btn-outline-secondary btn-sm" (click)="svc.close(false)">{{ svc.state().cancelLabel }}</button>
            <button class="btn btn-sm" [class.btn-danger]="svc.state().danger" [class.btn-primary]="!svc.state().danger" (click)="svc.close(true)">{{ svc.state().confirmLabel }}</button>
          </div>
        </div>
      </div>
    }
  `
})
export class ConfirmDialogComponent {
  constructor(public svc: ConfirmDialogService) {}
}
